return {
  name: 'paste-image-host',
  apply(ctx) {
    const EXT = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/gif': 'gif' }
    harness.handle('paste-image', async (args) => {
      try {
        const input = (args !== null && typeof args === 'object') ? args : {}
        const name = input.name
        const mediaType = input.mediaType
        const dataBase64 = input.dataBase64
        if (typeof dataBase64 !== 'string' || dataBase64.length === 0) {
          return { ok: false, error: 'no image data' }
        }
        const ext = EXT[mediaType]
        if (ext === undefined) {
          return { ok: false, error: 'unsupported media type: ' + String(mediaType) }
        }
        const rawBytes = Math.floor(dataBase64.length * 3 / 4)
        if (rawBytes > 16 * 1024 * 1024) {
          return { ok: false, error: 'image too large (max 16MB)' }
        }
        const fs = ctx.get('fs')
        if (fs === undefined) return { ok: false, error: 'fs service unavailable' }
        const sandboxPolicy = ctx.get('sandboxPolicy')
        const base = (sandboxPolicy !== undefined && typeof sandboxPolicy.workspaceRoot === 'string' && sandboxPolicy.workspaceRoot.length > 0)
          ? sandboxPolicy.workspaceRoot
          : '/absolute/path/to/your/harness/workspace'
        const dir = base.replace(/\/+$/, '') + '/pasted'
        const stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
        const rand = Math.random().toString(36).slice(2, 8)
        const safe = String(name || 'image').replace(/[^A-Za-z0-9._-]/g, '_').slice(-40)
        const stem = 'pasted-' + stamp + '-' + rand + '-' + safe
        const b64Path = dir + '/' + stem + '.' + ext + '.b64'
        const b64Target = await fs.resolve(b64Path)
        await fs.writeText(b64Target, dataBase64)
        const b64Abs = fs.processPath(b64Target)
        const shell = ctx.get('shell')
        if (shell !== undefined) {
          try {
            const outPath = dir + '/' + stem + '.' + ext
            const spec = shell.resolve({
              command: 'base64 -d < "' + b64Abs + '" > "' + outPath + '"',
              workdir: dir,
              timeoutMs: 15000
            })
            const result = await shell.run(spec)
            if (result.exitCode === 0) {
              return { ok: true, path: outPath, b64Path: b64Abs, name: stem + '.' + ext, mediaType, bytes: rawBytes, decoded: true }
            }
          } catch (error) {
            console.log('paste-image decode failed: ' + (error instanceof Error ? error.message : String(error)))
          }
        }
        return { ok: true, path: b64Abs, name: stem + '.' + ext + '.b64', mediaType, bytes: rawBytes, decoded: false }
      } catch (error) {
        console.error('paste-image error: ' + (error instanceof Error ? (error.stack || error.message) : String(error)))
        return { ok: false, error: error instanceof Error ? error.message : String(error) }
      }
    })
  }
}

