return {
  name: 'paste-image-client',
  apply(ctx) {
    const readAsBase64 = (file) => new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => {
        const result = reader.result
        if (typeof result !== 'string') { reject(new Error('read failed')); return }
        const comma = result.indexOf(',')
        resolve(comma >= 0 ? result.slice(comma + 1) : result)
      }
      reader.onerror = () => reject(reader.error || new Error('read failed'))
      reader.readAsDataURL(file)
    })
    const composerTextarea = () => {
      const backdrop = document.querySelector('[data-input-backdrop]')
      const el = backdrop !== null && backdrop !== undefined ? backdrop.nextElementSibling : null
      return el !== null && el.tagName === 'TEXTAREA' ? el : null
    }
    const insertMarker = (marker) => {
      try {
        const textarea = composerTextarea()
        if (textarea === null) return false
        if (document.activeElement !== textarea) textarea.focus()
        const ev = new ClipboardEvent('paste')
        Object.defineProperty(ev, 'clipboardData', { value: {
          getData: (type) => type === 'text/plain' ? marker : '',
          setData: () => {},
          items: [],
          types: ['text/plain']
        } })
        textarea.dispatchEvent(ev)
        return true
      } catch (error) {
        try {
          const textarea = composerTextarea()
          if (textarea !== null) {
            textarea.focus()
            document.execCommand('insertText', false, marker)
            return true
          }
        } catch (error2) {}
        return false
      }
    }
    const handlePaste = async (e) => {
      try {
        const target = e.target
        if (target === null || typeof target.closest !== 'function') return
        const card = target.closest('[data-composer-card]')
        if (card === null) return
        const items = e.clipboardData !== null && e.clipboardData !== undefined ? e.clipboardData.items : null
        if (items === null || items === undefined) return
        let imageItem = null
        for (const item of Array.from(items)) {
          if (item.kind === 'file' && typeof item.type === 'string' && item.type.startsWith('image/')) {
            imageItem = item
            break
          }
        }
        if (imageItem === null) return
        const file = typeof imageItem.getAsFile === 'function' ? imageItem.getAsFile() : null
        if (file === null) return
        e.preventDefault()
        e.stopPropagation()
        const dataBase64 = await readAsBase64(file)
        const result = await host.call('paste-image', { name: file.name || 'image', mediaType: file.type, dataBase64 })
        if (result !== null && result !== undefined && result.ok === true) {
          insertMarker('[粘贴图片已保存: ' + result.path + ']')
        } else {
          const message = result !== null && result !== undefined && typeof result.error === 'string' ? result.error : 'unknown error'
          insertMarker('[粘贴图片失败: ' + message + ']')
        }
      } catch (error) {
        insertMarker('[粘贴图片失败: ' + (error instanceof Error ? error.message : String(error)) + ']')
      }
    }
    ctx.effect(() => {
      const handler = (e) => { void handlePaste(e) }
      document.addEventListener('paste', handler, true)
      return () => document.removeEventListener('paste', handler, true)
    })
  }
}
